/* MODULE kn10 · Bước 5 Chọn kênh · Kế hoạch truyền thông tích hợp (IMC)
   10 bài × 7 câu. Module tổng hợp: ghép các kênh thành một kế hoạch. Mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kn10', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kn10-01', skill:'channel', read:'6 phút', t:'Năm kênh chạy năm câu chuyện — sao khách không nhớ gì?',
  situation:'Một hãng nước ép đóng chai ở TP.HCM chạy cùng lúc: TVC nói "tươi từ vườn", KOL TikTok làm thử thách nhảy, banner siêu thị ghi "mua 2 tặng 1", fanpage đăng mẹo giảm cân, email gửi mã giảm giá sinh nhật. Tổng chi 1,2 tỷ trong hai tháng. Khảo sát sau chiến dịch: rất ít người nhớ hãng nói gì.',
  concept:{ name:'Ý tưởng lớn xuyên kênh (big idea)',
    body:'Truyền thông tích hợp bắt đầu từ <b>một ý tưởng</b> mà mọi kênh kể lại theo cách riêng. Hai tiêu chí chọn ý: <b>đủ rộng</b> khi mỗi kênh tìm được chất liệu thật để quay, in, gửi; <b>đủ hẹp</b> khi đối thủ không thể nói y như vậy. Quá rộng ("sống khoẻ") thì kênh nào cũng kể được nhưng khách không nhận ra là của ai. Quá hẹp (một đợt khuyến mãi) thì chỉ sống được ở một kênh. Khi mỗi kênh tự nghĩ một ý, ngân sách bị chia thành nhiều chiến dịch nhỏ, mỗi cái đều quá yếu để được nhớ. Phép thử: che logo đi, khách xem hai điểm chạm bất kỳ có nhận ra cùng một chiến dịch không.' },
  example:'Hãng chọn một ý: "Sáng nay vườn hái, chiều nay bạn uống". TVC quay cảnh hái lúc 5 giờ sáng. KOL TikTok ghé vườn thật và quay đồng hồ. Kệ siêu thị in giờ hái trên nhãn. Fanpage đăng nhật ký vườn mỗi ngày. Email gửi khách cũ ảnh lô hàng tuần này. Cùng 1,2 tỷ, nhưng năm kênh cùng đẩy một ý nên mỗi lần khách gặp lại là một lần nhớ thêm, không phải bắt đầu từ đầu.',
  takeaway:'Nghĩ ra một ý tưởng trước, rồi mới hỏi mỗi kênh sẽ kể ý đó thế nào.',
  apply:'Chọn một chiến dịch bạn vừa thấy. Nói trong 60 giây: ý tưởng chung là gì, và có kênh nào đang kể một chuyện khác không.',
  mistakes:['Giao mỗi kênh cho một người tự nghĩ nội dung rồi gộp lại gọi là IMC.','Nhầm ý tưởng xuyên kênh với việc dùng chung logo và màu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao khách không nhớ gì dù hãng nước ép đã chi 1,2 tỷ trên năm kênh?',
    options:[{k:'a',t:'Mỗi kênh kể một ý riêng nên không ý nào đủ lặp lại để được nhớ'},{k:'b',t:'1,2 tỷ là quá ít cho năm kênh, cần gấp đôi ngân sách mới đủ để khách bắt đầu nhớ'},
             {k:'c',t:'TikTok không hợp với ngành đồ uống nên kéo cả chiến dịch đi xuống'},{k:'d',t:'Hai tháng là quá ngắn để khách nhớ bất kỳ thông điệp nào của hãng'}],
    answer:'a', why:{a:'Đúng. Năm thông điệp khác nhau chia nhỏ sự chú ý; mỗi ý chỉ được nghe một lần.',
      b:'Ngân sách có thể chưa lớn, nhưng gấp đôi mà vẫn năm ý rời thì vẫn khó nhớ.',
      c:'Đồ uống vẫn bán tốt trên TikTok; vấn đề là thử thách nhảy không nối với gì cả.',
      d:'Hai tháng đủ để nhớ một ý nếu ý đó được lặp lại; ở đây mỗi ý chỉ xuất hiện đúng một lần.'} },
  { type:'mcq', stem:'Bạn được giao làm lại chiến dịch với cùng ngân sách. Việc đầu tiên bạn làm là gì?',
    options:[{k:'a',t:'Chọn kênh hiệu quả nhất từ lần trước và dồn phần lớn tiền vào đó'},{k:'b',t:'Chốt một ý tưởng chung, rồi để mỗi kênh kể ý đó theo thế mạnh riêng'},
             {k:'c',t:'Yêu cầu năm kênh dùng đúng một câu slogan, cùng một hình ảnh, cùng kích thước'},{k:'d',t:'Tăng tần suất đăng trên cả năm kênh để khách thấy hãng nhiều hơn'}],
    answer:'b', why:{a:'Một kênh có thể hiệu quả nhất nhưng khó chạm đủ người; vấn đề gốc là thiếu ý chung.',
      b:'Đúng. Ý tưởng đi trước, kênh đi sau — mỗi kênh kể cùng một chuyện theo cách của nó.',
      c:'Nhất quán không có nghĩa là sao chép; banner kệ và video TikTok cần định dạng khác nhau.',
      d:'Đăng nhiều hơn năm ý rời chỉ làm khách rối hơn.'} },
  { type:'mcq', stem:'Phép thử nhanh nhất để biết các điểm chạm có thuộc cùng một ý tưởng hay không là gì?',
    options:[{k:'a',t:'Kiểm tra xem các ấn phẩm đã đặt logo đúng vị trí và đúng màu chưa'},{k:'b',t:'Đếm xem ý tưởng được nhắc bao nhiêu lần trong mỗi bài đăng trên fanpage'},
             {k:'c',t:'Che logo, đưa hai điểm chạm bất kỳ cho người lạ xem họ có nhận ra không'},{k:'d',t:'Hỏi agency xem họ đã làm theo bản brief chung chưa'}],
    answer:'c', why:{a:'Logo đúng chỗ vẫn có thể đi kèm năm câu chuyện khác nhau.',
      b:'Đếm số lần nhắc chỉ đo một kênh, không đo sự liên kết giữa các kênh.',
      c:'Đúng. Nếu không có logo mà vẫn nhận ra, ý tưởng đã đủ rõ để xuyên kênh.',
      d:'Agency làm theo brief chưa chắc kết quả nhận ra được là một.'} },
  { type:'mcq', stem:'Một chuỗi phở chọn ý tưởng "Nồi nước dùng ninh 12 tiếng". Cách kể nào trên TikTok vẫn giữ đúng ý?',
    options:[{k:'a',t:'Video tua nhanh 12 tiếng ninh xương trong 30 giây, kết ở bát phở'},{k:'b',t:'Thử thách ăn phở nhanh nhất có thưởng, hot trend đang lên'},
             {k:'c',t:'Livestream bán voucher giảm 30% cho khách đặt qua app giao đồ ăn'},{k:'d',t:'Đăng lại nguyên TVC 30 giây đã phát trên truyền hình, không cắt ghép gì'}],
    answer:'a', why:{a:'Đúng. Cùng ý "12 tiếng", kể bằng ngôn ngữ của TikTok (tua nhanh, dọc, ngắn).',
      b:'Ăn nhanh đi ngược với ý "chậm và kỹ"; có view nhưng xoá mất ý tưởng.',
      c:'Khuyến mãi có thể chạy kèm, nhưng một mình nó không kể ý tưởng nào.',
      d:'Đúng ý nhưng sai định dạng: video ngang của TV thường bị lướt qua trên TikTok.'} },
  { type:'mcq', stem:'Một chuỗi trà sữa ở Đà Nẵng có bốn ứng viên ý tưởng xuyên kênh. Ý nào vừa đủ rộng vừa đủ hẹp để dùng?',
    options:[{k:'a',t:'"Thương hiệu trà sữa số một được khách yêu thích nhất"'},{k:'b',t:'"Trà ngon cho mọi người, mọi lúc, mọi nơi trong ngày"'},
             {k:'c',t:'"Mua một ly tặng một ly vào mỗi thứ Ba hằng tuần"'},{k:'d',t:'"Trà ủ lạnh 8 tiếng, hết mẻ là hết, không pha lại"'}],
    answer:'d', why:{a:'Đây là lời tự khen, không có chất liệu nào để quay hay in; ai cũng nói được câu đó.',
      b:'Quá rộng: kênh nào cũng kể được nhưng khách không nhận ra là hãng nào, vì đối thủ nào cũng nói thế.',
      c:'Quá hẹp: là một đợt khuyến mãi, chỉ sống được ở banner và tin nhắn, không có chuyện để kể ở video hay fanpage.',
      d:'Đúng. Có bằng chứng nhìn thấy được (mẻ ủ, đồng hồ, bảng hết hàng) cho mỗi kênh, và đối thủ không nói y như vậy được.'} },
  { type:'mcq', stem:'Sếp nói: "Mình dùng chung logo, màu và font trên mọi kênh rồi, vậy là đã tích hợp." Bạn phản hồi thế nào?',
    options:[{k:'a',t:'Đồng ý, nhận diện đồng bộ chính là định nghĩa của truyền thông tích hợp'},{k:'b',t:'Nhận diện đồng bộ là cần, nhưng tích hợp là các kênh cùng kể chung một ý tưởng'},
             {k:'c',t:'Chưa đủ, cần thêm cùng một agency làm hết năm kênh mới là tích hợp'},{k:'d',t:'Chưa đủ, phải chạy các kênh cùng ngày khởi động thì mới tính là tích hợp'}],
    answer:'b', why:{a:'Đồng bộ hình thức không đảm bảo đồng bộ nội dung; năm ý khác nhau vẫn có thể cùng màu.',
      b:'Đúng. Màu sắc giúp nhận ra hãng; ý tưởng chung giúp nhớ hãng nói gì.',
      c:'Một agency vẫn có thể làm năm ý rời; nhiều agency vẫn có thể cùng một ý.',
      d:'Lịch khởi động là chuyện điều phối, không phải điều kiện của tích hợp.'} },
  { type:'calc', stem:'Cả chiến dịch mua được 6 triệu lượt tiếp xúc (số minh hoạ). Một người cần thấy cùng một ý khoảng 3 lần mới bắt đầu nhớ. Nếu chia đều cho 5 ý khác nhau, mỗi ý đủ lượt để bao nhiêu người thấy đủ 3 lần?',
    unit:'người', ans:400000, tol:1000, wrong:[[1200000,'SAI_MAU_SO'],[2000000,'SAI_TINH_TOAN'],[3600000,'NGUOC_TAN_SUAT']], errors:['SAI_MAU_SO','NGUOC_TAN_SUAT','SAI_TINH_TOAN'],
    steps:['Mỗi ý nhận 6.000.000 ÷ 5 = 1.200.000 lượt.','Mỗi người cần 3 lượt: 1.200.000 ÷ 3 = <b>400.000 người</b>.','Nếu cả 6 triệu lượt cùng đẩy một ý: 6.000.000 ÷ 3 = 2.000.000 người nhớ. Chia thành năm ý, số người nhớ còn 400.000 mỗi ý, và đó là một ý trong năm chứ không phải năm lần thắng.'] }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kn10-02', skill:'channel', read:'7 phút', t:'Mỗi kênh trong chiến dịch nên giữ vai trò gì?',
  situation:'Một thương hiệu sữa hạt ra dòng sản phẩm mới, ngân sách 800 triệu. Bản kế hoạch có năm kênh: YouTube, TikTok KOL, Shopee, fanpage, Zalo OA. Nhưng mọi kênh đều được giao cùng một mục tiêu là "ra đơn", nên KOL bị đánh giá bằng số đơn và YouTube bị cắt vì "không ra đơn".',
  concept:{ name:'Phân vai kênh theo hành trình',
    body:'Mỗi kênh làm tốt một việc khác nhau: có kênh để <b>nhiều người biết</b> (video tầm rộng), có kênh để <b>người ta cân nhắc</b> (KOL review, nội dung chi tiết), có kênh để <b>chốt đơn</b> (sàn, tìm kiếm), và có kênh để <b>giữ khách</b> (Zalo OA, email). Giao cùng một chỉ số cho mọi kênh sẽ khiến kênh tầm rộng luôn thua, bị cắt, rồi kênh chốt đơn cạn người để chốt. Kế hoạch tốt ghi rõ vai trò của từng kênh trước khi chia tiền.' },
  example:'Phân vai lại: YouTube 300 triệu — cho 2 triệu người biết dòng mới; TikTok KOL 200 triệu — cho người đã biết thấy vị thật; Shopee 200 triệu — chốt đơn, đo bằng ROAS; Zalo OA và fanpage 100 triệu — mời người đã mua quay lại. YouTube giờ được đo bằng độ phủ và mức nhớ, không bằng số đơn. Khi Shopee chậm đơn, câu hỏi đầu tiên là phễu phía trên có đủ người không.',
  takeaway:'Mỗi kênh một vai; đo mỗi kênh bằng đúng việc nó được giao.',
  apply:'Lấy một chiến dịch bạn biết. Nói trong 60 giây: kênh nào làm biết, kênh nào làm tin, kênh nào chốt, kênh nào giữ.',
  mistakes:['Bắt mọi kênh báo cáo số đơn rồi cắt kênh tầm rộng.','Cho hai kênh cùng một vai, trong khi bỏ trống vai giữ khách.'],
  q:[
  { type:'mcq', stem:'Đoán trước: nếu cắt YouTube vì "không ra đơn", điều gì dễ xảy ra với Shopee sau vài tuần?',
    options:[{k:'a',t:'Shopee tăng đơn vì được dồn thêm ngân sách từ YouTube'},{k:'b',t:'Không đổi gì, vì hai kênh độc lập với nhau về tệp khách'},
             {k:'c',t:'Shopee chậm dần vì ít người mới biết đến dòng sản phẩm để tìm mua'},{k:'d',t:'Shopee tăng mạnh vì khách chuyển thẳng từ YouTube sang sàn để mua với giá rẻ hơn'}],
    answer:'c', why:{a:'Có thể tăng ngắn hạn, nhưng tiền thêm không tạo thêm người biết đến sản phẩm.',
      b:'Người tìm trên sàn phần lớn là người đã biết từ kênh khác; hai kênh nối nhau.',
      c:'Đúng. Kênh chốt đơn sống nhờ người đã biết; cắt kênh làm biết thì đầu phễu cạn.',
      d:'Đã cắt YouTube thì không còn dòng khách nào chuyển từ đó sang.'} },
  { type:'mcq', stem:'Bạn phải chọn chỉ số chính cho TikTok KOL trong kế hoạch này. Bạn chọn gì?',
    options:[{k:'a',t:'Số đơn Shopee phát sinh trong ngày KOL đăng bài'},{k:'b',t:'Tỉ lệ xem hết video và lượng tìm kiếm tên sản phẩm tăng sau bài đăng'},
             {k:'c',t:'Số người theo dõi mới của trang KOL sau chiến dịch'},{k:'d',t:'Số lượt thích, vì đó là con số dễ lấy và dễ so sánh nhất giữa các KOL'}],
    answer:'b', why:{a:'KOL được giao vai làm tin, không phải chốt; đo bằng đơn trong ngày sẽ đánh giá sai.',
      b:'Đúng. Xem hết và tìm kiếm tăng cho thấy người xem đã quan tâm thật — đúng vai cân nhắc.',
      c:'Người theo dõi của KOL là tài sản của KOL, không phải của hãng.',
      d:'Lượt thích dễ lấy nhưng không cho biết người xem có cân nhắc mua hay không.'} },
  { type:'mcq', stem:'Vai "giữ khách" trong kế hoạch này nên giao cho kênh nào?',
    options:[{k:'a',t:'YouTube, vì chạm được nhiều người nhất'},{k:'b',t:'TikTok KOL, vì khách tin KOL hơn tin hãng'},
             {k:'c',t:'Shopee, vì khách đã mua ở đó rồi thì sẽ tự quay lại lần sau'},{k:'d',t:'Zalo OA, vì hãng nhắn trực tiếp cho người đã mua'}],
    answer:'d', why:{a:'Tầm rộng hợp để làm biết, không nhắm được người đã mua.',
      b:'KOL nói với người theo dõi của họ, không phải với khách của hãng.',
      c:'Khách trên sàn thuộc về sàn nhiều hơn; hãng khó chủ động nhắn lại.',
      d:'Đúng. Kênh sở hữu cho phép nhắc lại người đã mua với chi phí thấp.'} },
  { type:'calc', stem:'Ngân sách 800 triệu, YouTube nhận 300 triệu. YouTube chiếm bao nhiêu phần trăm ngân sách?',
    unit:'%', ans:37.5, tol:0.1, wrong:[[266.7,'SAI_MAU_SO'],[2.67,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ trọng = ngân sách kênh ÷ tổng ngân sách.','300 ÷ 800 = 0,375 = <b>37,5%</b>.'] },
  { type:'mcq', stem:'Một kế hoạch có Facebook Ads và TikTok Ads cùng nhắm tệp rộng để làm biết, nhưng không kênh nào lo giữ khách. Bạn sửa thế nào?',
    options:[{k:'a',t:'Chuyển một phần tiền từ một kênh tầm rộng sang kênh sở hữu để giữ khách'},{k:'b',t:'Giữ nguyên, vì hai kênh tầm rộng phủ càng lớn thì càng ra nhiều đơn hơn'},
             {k:'c',t:'Tăng ngân sách cho cả hai kênh tầm rộng để bù cho phần giữ khách'},{k:'d',t:'Bỏ cả hai kênh tầm rộng để dồn tiền cho khuyến mãi trên sàn'}],
    answer:'a', why:{a:'Đúng. Hai kênh trùng vai trong khi một vai bị bỏ trống; chuyển tiền để lấp chỗ trống.',
      b:'Phủ thêm có ích, nhưng khách đã mua rồi rơi mất thì chi phí làm biết bị lãng phí.',
      c:'Tăng tiền tầm rộng không làm được việc giữ khách.',
      d:'Bỏ hết tầm rộng thì đầu phễu cạn; vấn đề chỉ là thiếu vai giữ khách.'} },
  { type:'mcq', stem:'Cuối tháng, YouTube có chi phí mỗi đơn cao gấp năm lần Shopee. Nhận định nào đúng nhất?',
    options:[{k:'a',t:'YouTube kém hiệu quả, nên cắt ngay, dồn tiền sang Shopee'},{k:'b',t:'So sánh này lệch vì YouTube không được giao vai chốt đơn'},
             {k:'c',t:'Shopee rẻ hơn năm lần nghĩa là Shopee tốt hơn gấp năm lần'},{k:'d',t:'Cần tăng giá bán trên YouTube để bù lại chi phí mỗi đơn quá cao'}],
    answer:'b', why:{a:'Cắt kênh làm biết theo chỉ số của kênh chốt là lỗi phân vai kinh điển.',
      b:'Đúng. Đo YouTube bằng độ phủ và mức nhớ; chi phí mỗi đơn là thước đo của kênh chốt.',
      c:'Shopee rẻ vì nó thu hoạch người mà kênh khác đã làm cho biết.',
      d:'YouTube không bán trực tiếp; không có giá bán nào trên YouTube để tăng.'} },
  { type:'mcq', stem:'Câu nào mô tả đúng nhất việc phân vai kênh trong một kế hoạch tích hợp?',
    options:[{k:'a',t:'Kênh nào rẻ nhất thì giao nhiều việc nhất để tiết kiệm'},{k:'b',t:'Kênh nào cũng làm đủ việc để không sót khách ở giai đoạn nào'},
             {k:'c',t:'Ghi rõ mỗi kênh làm việc gì trong hành trình và đo bằng chỉ số nào'},{k:'d',t:'Để agency từng kênh tự quyết vai trò vì họ hiểu kênh hơn'}],
    answer:'c', why:{a:'Kênh rẻ chưa chắc làm được mọi việc; rẻ để chốt không có nghĩa rẻ để làm biết.',
      b:'Kênh nào cũng làm đủ việc nghĩa là không kênh nào làm sâu việc gì.',
      c:'Đúng. Vai trò và chỉ số đi cùng nhau, ghi trước khi chia tiền.',
      d:'Agency hiểu kênh, nhưng vai trò phải do người giữ bức tranh chung quyết.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kn10-03', skill:'channel', read:'7 phút', t:'Chiến dịch Tết nên bắt đầu từ lúc nào?',
  situation:'Một hãng bánh kẹo lên kế hoạch Tết với 3 tỷ. Bản nháp dồn toàn bộ tiền vào 3 tuần trước Tết: TVC, KOL, khuyến mãi siêu thị cùng nổ một lúc. Không có gì chạy trước để khách biết mẫu hộp mới, và không có gì chạy sau Tết để giữ người đã mua.',
  concept:{ name:'Lịch chiến dịch ba pha: trước – trong – sau',
    body:'Một chiến dịch có ba pha. <b>Trước</b> (teasing, làm nóng): gieo ý tưởng, cho khách biết sắp có gì, xây tệp để nhắm lại. <b>Trong</b> (cao điểm): độ phủ lớn nhất, khuyến mãi, kênh chốt đơn chạy mạnh. <b>Sau</b> (duy trì): cảm ơn, nhắc mua lại, thu nội dung khách tạo ra. Dồn hết vào cao điểm thì tiền đắt nhất (giá quảng cáo mùa cao điểm tăng) mà người xem lần đầu nghe đến bạn đúng lúc họ đã quyết. Độ dài pha trước theo chu kỳ mua: quà biếu doanh nghiệp phải duyệt và đặt sớm nhiều tuần, khách lẻ mua sát Tết, nên chia theo tệp chứ không dùng một mốc chung.' },
  example:'Chia lại 3 tỷ, mỗi khoản tính từ việc cần làm (số minh hoạ). Pha trước (6 đến 3 tuần trước Tết): cần gom 400.000 người xem hết video hộp quà mới. Giả sử 1.500 đồng một lượt xem hết thì 600 triệu, cộng 150 triệu quay dựng, thành 750 triệu. Pha sau (2 tuần sau Tết): Zalo OA mời 120.000 người đã mua, mỗi người tốn khoảng 3.750 đồng tin nhắn và mã mua lại, thành 450 triệu. Còn 1,8 tỷ cho pha trong: TVC, KOL, khuyến mãi, nhắm lại tệp đã gom. Tỉ lệ 25% và 15% là kết quả, không phải công thức để sao chép.',
  takeaway:'Pha trước làm cho pha trong rẻ hơn; pha sau làm cho khách quay lại.',
  apply:'Lấy một dịp lễ sắp tới. Nói trong 60 giây: mỗi pha chạy kênh gì và bắt đầu ngày nào.',
  mistakes:['Dồn toàn bộ ngân sách vào tuần cao điểm khi giá quảng cáo đắt nhất.','Tắt hết kênh ngay sau ngày lễ, bỏ phí tệp khách vừa mua.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì dễ xảy ra khi dồn toàn bộ 3 tỷ vào 3 tuần cuối trước Tết?',
    options:[{k:'a',t:'Hiệu quả tốt nhất, vì khách mua nhiều nhất đúng vào lúc đó'},{k:'b',t:'Tốn tiền hơn cho mỗi lượt tiếp cận và nhiều khách đã chọn xong hãng khác'},
             {k:'c',t:'Siêu thị từ chối trưng bày vì hãng không đặt hàng sớm'},{k:'d',t:'Khách mệt vì quảng cáo dày trong thời gian ngắn nên bỏ qua cả chiến dịch'}],
    answer:'b', why:{a:'Khách mua nhiều lúc cao điểm, nhưng nhiều người đã quyết hãng từ trước đó.',
      b:'Đúng. Cao điểm là lúc giá quảng cáo đắt và khách đã có lựa chọn; xuất hiện lần đầu lúc đó là muộn.',
      c:'Chuyện trưng bày tuỳ hợp đồng, không phải hệ quả của lịch truyền thông.',
      d:'Quảng cáo dày có thể gây nhàm, nhưng nguyên nhân chính là chi phí cao và xuất hiện quá muộn, đúng lúc khách đã chọn xong.'} },
  { type:'mcq', stem:'Bạn chỉ được thêm một pha vào bản nháp. Bạn chọn thêm pha nào và vì sao?',
    options:[{k:'a',t:'Pha sau Tết, vì khách đang có tiền lì xì và dễ mua thêm hơn'},{k:'b',t:'Pha Rằm tháng Giêng, vì khách còn mua quà đi chúc Tết muộn'},
             {k:'c',t:'Pha trước, để gom tệp người quan tâm và nhắm lại họ ở cao điểm'},{k:'d',t:'Không thêm pha nào, dồn tiền để TVC phát dày hơn trong 3 tuần cuối'}],
    answer:'c', why:{a:'Pha sau hữu ích, nhưng nếu không có pha trước thì cao điểm vẫn đắt và muộn.',
      b:'Nhu cầu quà Tết đã tắt sau Tết; pha này không giúp cao điểm bớt đắt hay bớt muộn.',
      c:'Đúng. Pha trước biến cao điểm từ "gặp lần đầu" thành "nhắc lại người đã biết".',
      d:'Phát dày hơn tăng tần suất nhưng không giải quyết việc xuất hiện muộn.'} },
  { type:'calc', stem:'Pha trước cần gom 400.000 người xem hết video. Cứ 10 người được tiếp cận thì có 2 người xem hết. Cần tiếp cận tối thiểu bao nhiêu người?',
    unit:'người', ans:2000000, tol:1000, wrong:[[80000,'SAI_MAU_SO'],[200000,'SAI_TINH_TOAN'],[4000000,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Tỉ lệ xem hết = 2 ÷ 10 = 20%.','Số người cần tiếp cận = 400.000 ÷ 20% = <b>2.000.000 người</b>.','Từ con số này mới suy ra ngân sách pha trước: số lượt tiếp cận nhân giá mỗi lượt, không lấy tỉ lệ có sẵn.'] },
  { type:'mcq', stem:'Trong pha trước, kênh nào đóng vai trò chính?',
    options:[{k:'a',t:'Video kể chuyện tầm rộng và nội dung gom tệp để nhắm lại'},{k:'b',t:'Khuyến mãi mua 2 tặng 1 ở siêu thị cho các dòng bánh Tết'},
             {k:'c',t:'Tin nhắn Zalo cảm ơn khách đã mua Tết năm ngoái'},{k:'d',t:'Quảng cáo tìm kiếm cho từ khoá "mua bánh Tết giá rẻ" với giá thầu cao nhất'}],
    answer:'a', why:{a:'Đúng. Pha trước gieo ý tưởng và gom người quan tâm để dùng ở cao điểm.',
      b:'Khuyến mãi sớm làm khách chờ giảm giá và bào lãi trước khi mùa bắt đầu.',
      c:'Nhắc khách cũ có ích, nhưng là việc của pha sau hoặc bổ trợ, không phải vai chính.',
      d:'Tìm kiếm là kênh chốt; người tìm "giá rẻ" chưa nhiều ở pha trước.'} },
  { type:'mcq', stem:'Một chuỗi thời trang chạy chiến dịch 11.11. Việc nào thuộc pha sau?',
    options:[{k:'a',t:'Đếm ngược trên fanpage từ ngày 1/11'},{k:'b',t:'Livestream xả hàng đúng đêm 11/11 cho người đã lưu giỏ và theo dõi kênh từ trước'},
             {k:'c',t:'Chạy quảng cáo lưu giỏ hàng trước ngày 11'},{k:'d',t:'Gửi hướng dẫn phối đồ cho người đã mua kèm mã cho lần sau'}],
    answer:'d', why:{a:'Đếm ngược là làm nóng — pha trước.',
      b:'Livestream đêm hội là cao điểm — pha trong.',
      c:'Nhắc lưu giỏ trước ngày hội là pha trước.',
      d:'Đúng. Chăm người vừa mua và mời quay lại là việc của pha sau.'} },
  { type:'mcq', stem:'Vì sao nhiều hãng vẫn cắt pha sau dù biết nó hữu ích?',
    options:[{k:'a',t:'Pha sau không đem lại gì đo được nên không ai được khen'},{k:'b',t:'Kết quả pha sau đến chậm, trong khi ngân sách thường bị đánh giá ngay cuối mùa'},
             {k:'c',t:'Khách sau lễ đã tiêu hết tiền nên không còn nhu cầu mua gì nữa cho tới dịp lễ năm sau'},{k:'d',t:'Pha sau đòi hỏi agency riêng nên tốn phí quản lý rất cao'}],
    answer:'b', why:{a:'Pha sau đo được: tỉ lệ mua lại, nội dung khách tạo, người mở tin nhắn.',
      b:'Đúng. Lợi ích của pha sau lộ ra sau vài tuần, khi báo cáo mùa đã chốt.',
      c:'Khách vẫn có nhu cầu; bánh kẹo, thời trang đều có dịp mua tiếp.',
      d:'Pha sau thường dùng kênh sở hữu rẻ, không cần agency riêng.'} },
  { type:'mcq', stem:'Pha trước chạy 3 tuần, gom được 400.000 người xem hết video. Ở pha trong, cách dùng tệp này hợp lý nhất là gì?',
    options:[{k:'a',t:'Bỏ qua tệp này để tìm người mới, vì họ đã xem rồi'},{k:'b',t:'Gửi đúng video cũ thêm năm lần cho họ trong tuần cao điểm'},
             {k:'c',t:'Nhắm lại họ bằng nội dung bước tiếp: nơi mua, ưu đãi, đánh giá'},{k:'d',t:'Bán tệp cho đối tác để thu lại một phần ngân sách pha trước'}],
    answer:'c', why:{a:'Họ là người nóng nhất; bỏ qua là lãng phí tiền pha trước.',
      b:'Lặp lại video cũ không đưa họ tiến thêm bước nào.',
      c:'Đúng. Tệp đã biết cần thông tin để quyết: mua ở đâu, giá sao, người khác nói gì.',
      d:'Tệp quảng cáo không bán được và cũng không nên chia sẻ dữ liệu khách như vậy.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kn10-04', skill:'channel', read:'7 phút', t:'Khách gặp thương hiệu theo thứ tự nào?',
  situation:'Một chuỗi phòng gym ở Hà Nội chạy chiến dịch tháng 1. Quảng cáo Facebook dẫn người xem vào thẳng trang "Đăng ký gói 12 tháng — 9 triệu". Tỉ lệ đăng ký dưới 0,3%. Khảo sát nhỏ cho thấy phần lớn người bấm chưa từng nghe tên phòng gym và chưa biết nó ở đâu.',
  concept:{ name:'Chuỗi điểm chạm (customer journey)',
    body:'Khách hiếm khi mua ở lần gặp đầu tiên với một món đắt. Họ đi qua một <b>chuỗi điểm chạm</b>: thấy lần đầu, tìm hiểu thêm, so sánh, thử, rồi mới mua. Kế hoạch tích hợp vẽ chuỗi này ra, đặt mỗi kênh vào đúng chỗ với lời mời phù hợp, và đo <b>tỉ lệ đi tiếp ở từng bước</b>: bước nào rơi mạnh nhất thì sửa bước đó, không đổ thêm tiền vào đầu chuỗi. Hỏi người mới gặp "đăng ký 12 tháng" giống cầu hôn ở lần gặp đầu. Món càng đắt, chuỗi càng dài; món rẻ mua theo thói quen thì chuỗi có thể chỉ một hai bước.' },
  example:'Vẽ lại: (1) video TikTok ngắn giới thiệu phòng và huấn luyện viên → (2) người xem hết được nhắm lại bằng bài "một ngày ở phòng" kèm địa chỉ → (3) mời đặt buổi tập thử miễn phí qua Zalo → (4) sau buổi thử, tư vấn gói 3 tháng → (5) tháng thứ hai mời nâng lên 12 tháng. Mỗi bước chỉ xin một việc nhỏ. Cùng 20.000 người xem (số minh hoạ): mời thẳng, 0,3% đăng ký là 60 gói 12 tháng. Theo chuỗi: 5% đặt thử là 1.000 người, 60% đến thật là 600, 25% mua gói 3 tháng là 150. Chuỗi cho gấp 2,5 lần người, nhưng gói 3 tháng rẻ hơn, nên so doanh thu phải nhân với giá từng gói.',
  takeaway:'Xin khách đúng một bước tiếp theo, không xin cả hành trình trong một lần.',
  apply:'Chọn một sản phẩm đắt bạn từng mua. Kể lại trong 60 giây các điểm chạm theo thứ tự trước khi bạn trả tiền.',
  mistakes:['Dẫn người lạ vào thẳng trang thanh toán của món đắt.','Vẽ hành trình nhưng dùng cùng một lời mời ở mọi bước.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao quảng cáo dẫn thẳng vào trang "Đăng ký 12 tháng" có tỉ lệ thấp?',
    options:[{k:'a',t:'Giá 9 triệu cao hơn đối thủ nên khách bỏ đi'},{k:'b',t:'Trang đăng ký thiết kế xấu, tải chậm trên điện thoại và thiếu nút gọi ngay'},
             {k:'c',t:'Người xem còn chưa biết phòng gym là ai mà đã bị xin quyết định lớn'},{k:'d',t:'Tháng 1 là tháng người ta ít quan tâm tập luyện nhất'}],
    answer:'c', why:{a:'Giá có thể là một yếu tố, nhưng khảo sát cho thấy khách chưa biết cả tên phòng.',
      b:'Trang tải chậm có thể làm tệ hơn, nhưng không giải thích chuyện khách chưa biết phòng gym.',
      c:'Đúng. Bị xin quyết định 12 tháng ở lần gặp đầu là nhảy cóc cả chuỗi.',
      d:'Tháng 1 thường là lúc nhiều người muốn bắt đầu tập — ngược lại.'} },
  { type:'mcq', stem:'Bạn được sửa đúng một điểm trong chuỗi. Bạn chọn lời mời nào cho quảng cáo đầu tiên?',
    options:[{k:'a',t:'"Tập thử một buổi miễn phí với huấn luyện viên, chọn giờ ngay trên Zalo"'},{k:'b',t:'"Giảm 20% gói 12 tháng, chỉ còn 7,2 triệu nếu đăng ký trong hôm nay"'},
             {k:'c',t:'"Theo dõi fanpage để nhận thông tin sớm nhất về các lớp tập mới"'},{k:'d',t:'"Đăng ký gói 12 tháng, tặng kèm áo và bình nước thương hiệu của phòng"'}],
    answer:'a', why:{a:'Đúng. Buổi thử là bước nhỏ, rủi ro thấp, đúng mức với người mới biết.',
      b:'Giảm giá vẫn xin quyết định 12 tháng từ người lạ.',
      c:'Bước quá nhỏ và không đưa khách tới gần việc thử phòng.',
      d:'Quà tặng không làm quyết định 12 tháng nhẹ hơn với người chưa biết phòng.'} },
  { type:'calc', stem:'Một đợt quảng cáo có 8.000 người xem hết video. Trong số đó 10% đặt buổi tập thử, 70% người đặt đến thật, và 25% người đến mua gói 3 tháng. Có bao nhiêu hội viên mới?',
    unit:'người', ans:140, tol:0.5, wrong:[[200,'SAI_TINH_TOAN'],[2000,'SAI_TINH_TOAN'],[560,'QUEN_TI_LE_CHUYEN_DOI']], errors:['SAI_TINH_TOAN','QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Đặt thử: 8.000 × 10% = 800 người.','Đến thật: 800 × 70% = 560 người.','Mua gói: 560 × 25% = <b>140 người</b>. Bỏ bước "đến thật" sẽ ra 200, tức tính dư 60 người chưa từng bước vào phòng.'] },
  { type:'mcq', stem:'Tỉ lệ đi tiếp theo bước, tháng trước và tháng này. Xem hết video sang đặt thử: 10% và 10%. Đặt thử sang đến thật: 70% và 45%. Đến thật sang mua gói: 25% và 25%. Bạn sửa bước nào trước?',
    options:[{k:'a',t:'Xem hết video sang đặt thử, vì đây là bước đầu nên ảnh hưởng toàn chuỗi'},{k:'b',t:'Đến thật sang mua gói, vì tỉ lệ 25% là thấp nhất trong ba bước'},
             {k:'c',t:'Cả ba bước, bằng cách tăng ngân sách quảng cáo để kéo thêm người xem'},{k:'d',t:'Đặt thử sang đến thật, vì đây là bước duy nhất tụt so với tháng trước'}],
    answer:'d', why:{a:'Bước này giữ nguyên 10%; đổ tiền vào đây không chữa được chỗ rơi vừa xuất hiện.',
      b:'25% thấp nhưng không đổi; so tháng trước mới chỉ ra bước vừa hỏng. Tỉ lệ thấp nhất chưa chắc là bước cần sửa trước.',
      c:'Thêm người vào đầu chuỗi chỉ làm nhiều người hơn rơi đúng chỗ đó.',
      d:'Đúng. 70% xuống 45% là điểm rơi mới; kiểm tra nhắc lịch, thời gian chờ, khoảng cách đến phòng tập, rồi sửa.'} },
  { type:'mcq', stem:'Trong chuỗi của phòng gym, Zalo OA đảm nhận bước nào hợp lý nhất?',
    options:[{k:'a',t:'Giới thiệu phòng gym lần đầu cho người chưa biết'},{k:'b',t:'Xác nhận lịch tập thử, nhắc giờ và chăm sóc sau buổi thử'},
             {k:'c',t:'Chạy quảng cáo tầm rộng cho người trong bán kính 5 km'},{k:'d',t:'Đăng video huấn luyện viên để thu hút người xem mới trên mạng'}],
    answer:'b', why:{a:'Zalo OA chỉ nhắn được người đã kết nối; không dùng để làm quen người lạ.',
      b:'Đúng. Kênh nhắn trực tiếp hợp với việc giữ lịch hẹn và chăm sóc cá nhân.',
      c:'Đó là việc của quảng cáo mạng xã hội, không phải Zalo OA.',
      d:'Video thu hút người mới hợp với TikTok hoặc Reels hơn.'} },
  { type:'mcq', stem:'Một thương hiệu mỹ phẩm thấy nhiều người bỏ giỏ ở bước thanh toán. Điểm chạm nào nên thêm vào chuỗi?',
    options:[{k:'a',t:'Thêm một TVC để tăng độ nhận biết thương hiệu'},{k:'b',t:'Thuê thêm KOL để làm video giới thiệu sản phẩm mới'},
             {k:'c',t:'Tin nhắn nhắc giỏ hàng kèm giải đáp thắc mắc hay gặp ở bước đó'},{k:'d',t:'Giảm giá cho khách mới ngay tại trang chủ để kéo tỉ lệ vào giỏ'}],
    answer:'c', why:{a:'Người bỏ giỏ đã biết hãng; thiếu hụt nằm ở bước cuối, không ở đầu chuỗi.',
      b:'KOL làm tin ở bước giữa; người bỏ giỏ đã qua bước đó.',
      c:'Đúng. Sửa đúng chỗ rơi: nhắc lại và gỡ lý do dừng.',
      d:'Giảm giá đại trà tốn tiền cho cả người vốn sẽ mua; vấn đề ở bước cuối.'} },
  { type:'mcq', stem:'Câu nào mô tả đúng nhất cách viết lời mời theo chuỗi điểm chạm?',
    options:[{k:'a',t:'Mỗi bước xin khách một việc nhỏ, vừa đủ để đi tiếp bước sau'},{k:'b',t:'Các bước đều kêu gọi mua ngay để không bỏ lỡ ai sẵn sàng'},
             {k:'c',t:'Lời mời để ở bước cuối, các bước trước tập trung làm đẹp'},{k:'d',t:'Lời mời giống nhau qua các bước để khách nhớ thông điệp tốt'}],
    answer:'a', why:{a:'Đúng. Lời mời vừa sức với độ quen của khách ở từng bước.',
      b:'Kêu gọi mua ngay với người lạ đẩy họ đi; chỉ hợp với bước cuối.',
      c:'Bước nào không có lời mời thì khách không biết làm gì tiếp.',
      d:'Ý tưởng nhất quán, nhưng lời mời phải đổi theo bước.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kn10-05', skill:'channel', read:'7 phút', t:'Có 50 triệu thì kế hoạch khác 5 tỷ ở đâu?',
  situation:'Hai bản kế hoạch đặt cạnh nhau. Một tiệm bánh mì ở Đà Nẵng có 50 triệu cho ba tháng. Một hãng bánh mì đóng gói toàn quốc có 5 tỷ. Chủ tiệm nhỏ sao chép khung của hãng lớn: TVC, KOL, Facebook, TikTok, Google, Shopee — mỗi kênh vài triệu.',
  concept:{ name:'Số kênh theo ngân sách',
    body:'Mỗi kênh cần một mức tối thiểu để có tác dụng, và bạn ước được nó bằng phép tính ngược: <b>tiền tối thiểu = số kết quả cần có ÷ tỉ lệ chuyển đổi × giá mỗi nhấp</b>. Chẳng hạn Meta thường cần khoảng 50 sự kiện tối ưu mỗi 7 ngày cho mỗi nhóm quảng cáo thì hệ thống mới học xong; không đủ tiền cho mức đó thì tối ưu theo sự kiện nhẹ hơn (nhắn tin, nhấp) hoặc bỏ kênh. Cách chọn kênh: hỏi khách đang biết bạn từ đâu rồi dồn vào nơi khách sát nhất, cộng kênh sở hữu (không mất tiền mua chỗ, vẫn tốn công). Ngân sách lớn mới đủ ngưỡng cho nhiều kênh và phân vai đầy đủ. Ý tưởng vẫn một, số kênh thay đổi.' },
  example:'Tiệm bánh mì hỏi khách một tuần "anh chị biết tiệm từ đâu": 62% ở hoặc đi ngang trong 2 km, 25% thấy trên Google Maps, 13% bạn giới thiệu (minh hoạ). Tối ưu theo đơn cần 50 đơn × 150.000đ = 7,5 triệu mỗi tuần, trong khi 50 triệu chia 13 tuần chỉ khoảng 3,8 triệu. Nên tiệm chạy Facebook bán kính 2 km, tối ưu theo tin nhắn đặt bánh (30 triệu), hai food reviewer địa phương (10 triệu), bảng hiệu và tờ rơi (10 triệu); Zalo OA và Maps tự làm. Hãng 5 tỷ đủ ngưỡng cho TVC 2 tỷ, KOL 1 tỷ, siêu thị 1,2 tỷ, sàn 600 triệu, kênh sở hữu 200 triệu.',
  takeaway:'Ngân sách nhỏ thì ít kênh và sâu; ngân sách lớn mới phủ rộng và phân vai đầy đủ.',
  apply:'Giả sử bạn có 20 triệu cho một quán cà phê. Nói trong 60 giây: bạn chọn tối đa mấy kênh, kênh nào, và vì sao.',
  mistakes:['Rải ngân sách nhỏ lên sáu kênh để "có mặt ở mọi nơi".','Bỏ qua kênh sở hữu ít tốn tiền như Google Maps, Zalo OA khi ngân sách eo hẹp.'],
  q:[
  { type:'mcq', stem:'Đoán trước: tiệm bánh mì chia 50 triệu cho sáu kênh, mỗi kênh vài triệu. Kết quả dễ gặp nhất là gì?',
    options:[{k:'a',t:'Kênh nào cũng quá mỏng để khách kịp nhớ, khó biết kênh nào có tác dụng'},{k:'b',t:'Phủ được nhiều người hơn nên doanh số tăng đều ở cả sáu kênh'},
             {k:'c',t:'TVC ra đơn nhiều nhất vì đó là kênh uy tín nhất trong sáu kênh'},{k:'d',t:'Hiệu quả tương đương dồn tiền vào một kênh vì tổng tiền vẫn như nhau, chỉ khác ở cách chia'}],
    answer:'a', why:{a:'Đúng. Dưới ngưỡng tối thiểu thì mỗi kênh gần như không để lại dấu vết.',
      b:'Phủ rộng mà mỏng thì mỗi người chỉ thấy một lần; khó thành nhớ, khó thành mua.',
      c:'Vài triệu không đủ cho một TVC nghiêm túc, chứ chưa nói phát sóng.',
      d:'Cùng tổng tiền nhưng chia mỏng làm mất ngưỡng tần suất; kết quả không tương đương.'} },
  { type:'mcq', stem:'Tiệm bánh mì có 50 triệu. Hỏi 100 khách: 62 ở gần tiệm, 25 thấy trên Google Maps, 13 do bạn giới thiệu. Bạn chọn cách nào?',
    options:[{k:'a',t:'Chia đều 12,5 triệu cho Facebook, TikTok, Google Ads và tờ rơi để thử kênh nào tốt'},{k:'b',t:'Dồn 40 triệu cho một KOL ẩm thực toàn quốc để kéo khách từ tỉnh khác tới'},
             {k:'c',t:'Quảng cáo Facebook theo bán kính 2 km, chăm hồ sơ Maps, giữ phần nhỏ cho reviewer địa phương'},{k:'d',t:'Chờ gom thêm ngân sách để chạy đủ các kênh như hãng lớn, trong lúc đó chỉ đăng bài miễn phí'}],
    answer:'c', why:{a:'Chia bốn phần là rải mỏng; kênh nào cũng dưới ngưỡng nên cuối kỳ không biết kênh nào có tác dụng.',
      b:'Số liệu cho thấy gần 90% khách ở quanh tiệm hoặc tìm trên Maps; KOL toàn quốc trả tiền cho người không thể đến mua.',
      c:'Đúng. Dồn tiền vào nơi khách thật sự đến từ, cộng kênh sở hữu ít tốn tiền.',
      d:'Chờ đợi mất doanh thu mỗi tuần; 50 triệu tập trung đúng nơi vẫn đủ để chạy.'} },
  { type:'calc', stem:'Meta cần khoảng 50 đơn mỗi tuần cho một nhóm quảng cáo để học xong. Giả định (minh hoạ) 2% lượt nhấp ra đơn, mỗi nhấp 3.000đ. Cần bao nhiêu triệu đồng mỗi tuần?',
    unit:'triệu đồng', ans:7.5, tol:0.05, wrong:[[0.15,'QUEN_TI_LE_CHUYEN_DOI'],[0.003,'SAI_MAU_SO']], errors:['QUEN_TI_LE_CHUYEN_DOI','SAI_MAU_SO'],
    steps:['Số nhấp cần = 50 đơn ÷ 2% = 2.500 nhấp.','Tiền = 2.500 × 3.000đ = 7.500.000đ = <b>7,5 triệu</b> mỗi tuần. Lấy 50 × 3.000đ = 150.000đ là quên tỉ lệ chuyển đổi.'] },
  { type:'mcq', stem:'Vì sao hãng 5 tỷ vẫn dành 200 triệu cho kênh sở hữu dù đã có TVC lớn?',
    options:[{k:'a',t:'Vì kênh sở hữu là nơi đăng lại TVC miễn phí để tiết kiệm'},{k:'b',t:'Vì kênh sở hữu giữ người đã mua, việc mà TVC không làm được'},
             {k:'c',t:'Vì đó là quy định bắt buộc của các nền tảng quảng cáo lớn'},{k:'d',t:'Vì kênh sở hữu thay được TVC nếu TVC phát sóng không hiệu quả như dự kiến'}],
    answer:'b', why:{a:'Kênh sở hữu có thể đăng lại TVC, nhưng đó không phải lý do để dành ngân sách.',
      b:'Đúng. TVC làm biết đại trà; kênh sở hữu giữ vai giữ khách với chi phí thấp.',
      c:'Không có quy định nào như vậy.',
      d:'Kênh sở hữu không chạm được người lạ, nên không thay được TVC.'} },
  { type:'mcq', stem:'Một nhóm quảng cáo tối ưu theo mua hàng chỉ ra khoảng 20 đơn mỗi tuần và báo "học hạn chế". Ngân sách không thể tăng. Bạn làm gì?',
    options:[{k:'a',t:'Đổi sang tối ưu theo bước nhẹ hơn như nhắn tin, để đủ sự kiện cho hệ thống học'},{k:'b',t:'Tăng giá thầu gấp đôi để hệ thống ép ra thêm đơn trong cùng số tiền'},
             {k:'c',t:'Chia thành bốn nhóm theo độ tuổi để mỗi nhóm học nhanh hơn trên tệp hẹp'},{k:'d',t:'Tắt quảng cáo đến khi có thêm tiền, vì dưới ngưỡng thì chắc chắn không ra đơn'}],
    answer:'a', why:{a:'Đúng. Sự kiện nhẹ xảy ra nhiều hơn nên đủ để học; đổi lại khách ít sẵn sàng mua hơn, cần theo dõi số đơn thật.',
      b:'Giá thầu cao hơn tốn thêm tiền cho mỗi nhấp, không làm sự kiện tăng gấp đôi khi tiền không đổi.',
      c:'Chia nhỏ làm mỗi nhóm có ít sự kiện hơn, nên càng xa ngưỡng hơn.',
      d:'Dưới ngưỡng thì học kém và kém ổn định, không phải chắc chắn không ra đơn; tắt là bỏ doanh thu đang có.'} },
  { type:'mcq', stem:'Điều gì GIỮ NGUYÊN giữa kế hoạch 50 triệu và 5 tỷ của cùng một thương hiệu?',
    options:[{k:'a',t:'Số nhóm quảng cáo chạy song song trên mỗi nền tảng'},{k:'b',t:'Chỉ số đo độ phủ cho kênh truyền hình và kênh video'},
             {k:'c',t:'Tỉ lệ phần trăm ngân sách cho từng kênh trả tiền, để dễ so sánh hai quy mô với nhau'},{k:'d',t:'Ý tưởng chung mà các kênh cùng kể'}],
    answer:'d', why:{a:'Ngân sách lớn đủ ngưỡng cho nhiều nhóm song song; ngân sách nhỏ chỉ đủ cho một hai nhóm.',
      b:'Kế hoạch nhỏ có thể không có kênh truyền hình.',
      c:'Tỉ lệ thay đổi theo quy mô; ngân sách nhỏ dồn nhiều hơn vào ít kênh.',
      d:'Đúng. Ý tưởng là phần cố định; kênh và tỉ lệ co giãn theo tiền.'} },
  { type:'mcq', stem:'Tiệm bánh mì chạy tốt, ngân sách tăng từ 50 lên 150 triệu. Bạn mở thêm kênh theo thứ tự nào?',
    options:[{k:'a',t:'Thêm cùng lúc TVC địa phương, Shopee, Google và KOL toàn quốc'},{k:'b',t:'Làm sâu kênh đang hiệu quả tới ngưỡng, rồi mới thêm từng kênh một'},
             {k:'c',t:'Chuyển phần lớn sang kênh mới để thử, bỏ kênh cũ vì đã bão hoà'},{k:'d',t:'Giữ nguyên kế hoạch cũ, phần tăng thêm để dành cho quý sau'}],
    answer:'b', why:{a:'Mở nhiều kênh cùng lúc lại rải mỏng và khó biết kênh nào góp phần.',
      b:'Đúng. Tăng dần từng kênh để mỗi kênh mới đều đủ ngưỡng và đo được.',
      c:'Bỏ kênh đang chạy tốt là mất nền; chưa có dấu hiệu bão hoà.',
      d:'Để dành bỏ lỡ đà tăng trưởng đang có.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kn10-06', skill:'channel', read:'6 phút', t:'Một thông điệp, nhưng mỗi kênh một hình dạng?',
  situation:'Hãng sữa chua uống có ý tưởng "Mỗi ngày một hũ, bụng nhẹ cả ngày". Agency làm một TVC 30 giây rồi dùng nguyên video đó cho TikTok, banner Shopee cắt từ khung hình TVC, poster siêu thị cũng vậy. Video trên TikTok bị lướt sau 2 giây, banner nhỏ đến mức không đọc được chữ.',
  concept:{ name:'Nhất quán ý, khác định dạng',
    body:'Tích hợp là giữ <b>ý tưởng, giọng và dấu hiệu nhận diện</b> giống nhau, nhưng để mỗi kênh có hình dạng riêng. TikTok cần video dọc, móc câu trong 2 giây đầu. Banner sàn cần một chữ lớn, sản phẩm rõ, đọc được trên điện thoại. Poster kệ cần đọc từ xa 2 mét. Email cần tiêu đề khiến người ta mở. Mỗi hình dạng có chỉ số kiểm tra riêng: tỉ lệ xem qua 3 giây đầu cho video dọc, CTR cho banner, tỉ lệ mở cho email. Sao chép một định dạng cho mọi nơi là nhất quán sai chỗ: đúng ý nhưng không ai tiếp nhận được.' },
  example:'Làm lại: TikTok — video dọc 15 giây, mở bằng cảnh ôm bụng sau bữa trưa, kết ở hũ sữa chua. Banner Shopee — nền trơn, chữ "Bụng nhẹ cả ngày" chiếm nửa khung, hũ sữa chua lớn. Poster kệ — hình hũ cỡ thật với chữ "1 hũ/ngày" đọc từ xa. Email khách cũ — tiêu đề "Tuần này bụng bạn thế nào?". Bốn hình dạng, một ý, cùng màu xanh và cùng hũ sữa chua ở vị trí trung tâm.',
  takeaway:'Giữ ý tưởng và dấu hiệu giống nhau; để hình dạng theo thói quen của từng kênh.',
  apply:'Lấy một câu thông điệp bạn thích. Nói trong 60 giây: trên TikTok, banner và poster, nó trông khác nhau thế nào.',
  mistakes:['Cắt một khung hình TVC làm banner cho mọi kênh.','Đổi luôn cả ý tưởng khi đổi định dạng, vì nghĩ mỗi kênh cần một câu chuyện riêng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao TVC 30 giây đăng nguyên trên TikTok bị lướt sau 2 giây?',
    options:[{k:'a',t:'TikTok hạn chế hiển thị video quảng cáo của các thương hiệu lớn'},{k:'b',t:'Người xem TikTok không quan tâm sữa chua vì đa số là người trẻ tuổi'},
             {k:'c',t:'Video ngang, mở chậm theo nhịp TV, không hợp thói quen lướt dọc'},{k:'d',t:'Ý tưởng "bụng nhẹ cả ngày" quá khó hiểu với khán giả mạng xã hội'}],
    answer:'c', why:{a:'Nền tảng không chặn quảng cáo của hãng lớn; vấn đề nằm ở định dạng.',
      b:'Người trẻ vẫn mua sữa chua; đó không phải lý do lướt.',
      c:'Đúng. Đúng ý nhưng sai định dạng thì người xem đi trước khi kịp nghe ý.',
      d:'Ý tưởng đơn giản; người xem không đợi đến đoạn nói ý.'} },
  { type:'mcq', stem:'Bạn phải làm banner Shopee cho chiến dịch. Bạn chọn phương án nào?',
    options:[{k:'a',t:'Cắt khung đẹp nhất của TVC, thêm logo và giá ở góc'},{k:'b',t:'Nền trơn, chữ "Bụng nhẹ cả ngày" lớn, hũ sữa chua rõ, đọc được ngay'},
             {k:'c',t:'Viết đầy đủ năm lợi ích sản phẩm để khách có đủ thông tin trước khi mua'},{k:'d',t:'Đổi sang thông điệp "Giảm 50%" vì trên sàn chỉ giá là quan trọng'}],
    answer:'b', why:{a:'Khung TVC thường nhiều chi tiết, thu nhỏ lại là không đọc được.',
      b:'Đúng. Cùng ý, định dạng hợp với màn hình nhỏ và cú lướt nhanh.',
      c:'Năm lợi ích trên banner nhỏ thành một khối chữ không ai đọc.',
      d:'Giá quan trọng trên sàn, nhưng bỏ ý tưởng thì banner tách khỏi chiến dịch.'} },
  { type:'mcq', stem:'Điều gì phải GIỐNG NHAU giữa các định dạng của cùng một chiến dịch?',
    options:[{k:'a',t:'Thời lượng video giữa các kênh'},{k:'b',t:'Kích thước và tỉ lệ khung hình'},
             {k:'c',t:'Số chữ trong tiêu đề ấn phẩm, để khách dễ đối chiếu ở các kênh'},{k:'d',t:'Ý tưởng, giọng nói và dấu hiệu nhận diện như màu, hình sản phẩm'}],
    answer:'d', why:{a:'Thời lượng đổi theo kênh: 6 giây, 15 giây, 30 giây.',
      b:'Mỗi kênh có tỉ lệ riêng: dọc, ngang, vuông.',
      c:'Số chữ đổi theo khoảng cách đọc và kích thước.',
      d:'Đúng. Đó là phần giúp khách nhận ra cùng một chiến dịch.'} },
  { type:'calc', stem:'Ngân sách sản xuất 60 triệu, mỗi ấn phẩm 2,5 triệu. Chiến dịch cần 4 định dạng, mỗi định dạng làm 2 phiên bản để thử. Sau khi làm đủ các bản thử, số tiền còn lại làm thêm được tối đa bao nhiêu ấn phẩm cho định dạng thắng?',
    unit:'ấn phẩm', ans:16, tol:0.5, wrong:[[24,'SAI_TINH_TOAN'],[8,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Bản thử = 4 định dạng × 2 phiên bản = 8 ấn phẩm = 8 × 2,5 = 20 triệu.','Còn 60 − 20 = 40 triệu; 40 ÷ 2,5 = <b>16 ấn phẩm</b>.','Dùng cả 60 triệu cho bản thử (24 ấn phẩm) thì không còn tiền nhân bản định dạng thắng.'] },
  { type:'mcq', stem:'Poster đặt ở kệ siêu thị, khách nhìn từ khoảng 2 mét. Yêu cầu nào quan trọng nhất?',
    options:[{k:'a',t:'Một hình lớn và vài chữ đọc được từ xa trong vài giây'},{k:'b',t:'Mã QR lớn dẫn về video TVC đầy đủ 30 giây trên YouTube'},
             {k:'c',t:'Nhiều thông tin dinh dưỡng để khách đọc kỹ khi đứng chờ thanh toán'},{k:'d',t:'Đường link website để khách tự tìm hiểu thêm'}],
    answer:'a', why:{a:'Đúng. Khách đi ngang lối kệ chỉ liếc vài giây từ xa.',
      b:'QR có thể thêm, nhưng người ta hiếm khi dừng quét để xem 30 giây giữa lối kệ.',
      c:'Chữ nhỏ không đọc được từ 2 mét.',
      d:'Không ai gõ link từ poster ở siêu thị.'} },
  { type:'mcq', stem:'Một agency đề xuất: "TikTok nên có câu chuyện riêng về thử thách nhảy, vì TikTok khác TV." Bạn phản hồi thế nào?',
    options:[{k:'a',t:'Đồng ý, mỗi kênh có khán giả riêng nên cần ý tưởng riêng cho từng nơi'},{k:'b',t:'Đồng ý nếu thử thách nhảy đang là xu hướng trên TikTok ở thời điểm chạy chiến dịch'},
             {k:'c',t:'Đổi định dạng thì được, nhưng thử thách phải kể được ý "bụng nhẹ cả ngày"'},{k:'d',t:'Từ chối TikTok, chỉ dùng TV để giữ thông điệp nhất quán'}],
    answer:'c', why:{a:'Mỗi kênh một ý là quay về tình trạng phân tán.',
      b:'Xu hướng có thể dùng, nhưng phải phục vụ ý tưởng chung.',
      c:'Đúng. Định dạng linh hoạt, ý tưởng cố định.',
      d:'Bỏ một kênh vì sợ lệch là quá tay; chỉ cần giữ ý tưởng.'} },
  { type:'mcq', stem:'Tiêu đề email nào vừa đúng định dạng email vừa đúng ý "Bụng nhẹ cả ngày"?',
    options:[{k:'a',t:'"Sữa chua uống mới: nhẹ bụng cả ngày, xem ngay tại đây"'},{k:'b',t:'"Tuần này bụng bạn thế nào?"'},
             {k:'c',t:'"5 lý do nên uống sữa chua mỗi ngày, cập nhật tháng 5"'},{k:'d',t:'"Giảm 20% sữa chua uống, chỉ đến hết Chủ nhật này"'}],
    answer:'b', why:{a:'Đúng ý nhưng là lời quảng cáo gửi đến người chưa có lý do mở; giống banner hơn là thư gửi một người.',
      b:'Đúng. Câu hỏi riêng cho người đọc khiến họ mở và nối thẳng với ý tưởng "bụng nhẹ".',
      c:'Là tiêu đề bài viết chung chung; không nhắc ý của chiến dịch và không riêng cho ai.',
      d:'Có thể được mở, nhưng đây là khuyến mãi, chiến dịch này không kể ý "bụng nhẹ cả ngày".'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kn10-07', skill:'comm', read:'7 phút', t:'Bốn agency, ai giữ câu chuyện chung?',
  situation:'Một hãng điện máy thuê bốn đơn vị: agency sáng tạo làm TVC, agency media mua quảng cáo, agency KOL, và một đội thương mại điện tử. Mỗi đơn vị có brief riêng, họp riêng với một người khác nhau bên hãng. Hai tuần trước ngày chạy, KOL đã quay xong với thông điệp giá rẻ trong khi TVC nói về độ bền.',
  concept:{ name:'Điều phối nhiều agency',
    body:'Nhiều đơn vị cùng làm một chiến dịch cần ba thứ: <b>một bản brief gốc</b> chung cho mọi bên (ý tưởng, đối tượng, vai kênh, chỉ số), <b>một người chủ trì</b> bên hãng có quyền quyết khi các bên lệch nhau (nên là người giữ mục tiêu kinh doanh, vì mỗi agency tối ưu thứ riêng: media thường được tính theo mức chi, sáng tạo theo ý tưởng), và <b>lịch chung</b> có điểm duyệt chéo — trước khi sản xuất, các bên xem bản nháp của nhau. Thiếu một trong ba, mỗi agency sẽ tối ưu phần việc của mình, và khách nhận về bốn chiến dịch.' },
  example:'Hãng điện máy làm lại: một brief gốc 2 trang gửi cùng lúc cho bốn bên. Trưởng nhóm thương hiệu là người chủ trì. Mỗi thứ Hai họp chung 30 phút. Có hai điểm duyệt chéo: kịch bản (mọi bên xem kịch bản của nhau) và bản dựng thô. Agency KOL thấy TVC nói về độ bền, nên đổi kịch bản sang "dùng 10 năm vẫn chạy êm". Tốn thêm 4 buổi họp, nhưng tránh được chi phí quay lại.',
  takeaway:'Một brief gốc, một người chủ trì, một lịch có điểm duyệt chéo.',
  apply:'Nghĩ về một dự án có nhiều bên cùng làm. Nói trong 60 giây: ai là người quyết khi các bên lệch nhau.',
  mistakes:['Gửi mỗi agency một brief do từng người viết.','Chỉ duyệt chéo khi mọi thứ đã sản xuất xong.'],
  q:[
  { type:'mcq', stem:'Đoán trước: nguyên nhân gốc khiến KOL nói giá rẻ còn TVC nói độ bền là gì?',
    options:[{k:'a',t:'Agency KOL làm việc cẩu thả, không đọc kỹ tài liệu'},{k:'b',t:'KOL tự ý đổi nội dung cho hợp khán giả'},
             {k:'c',t:'Không có brief gốc chung và không có điểm duyệt chéo'},{k:'d',t:'Agency sáng tạo gửi kịch bản TVC quá muộn cho các bên còn lại'}],
    answer:'c', why:{a:'Có thể agency đã làm đúng brief của họ; brief đó khác brief TVC.',
      b:'KOL có thể điều chỉnh, nhưng nếu có brief chung thì hướng đã được thống nhất.',
      c:'Đúng. Brief riêng, người nhận riêng, không ai xem bản của nhau — lệch là tất yếu.',
      d:'Gửi muộn chỉ là triệu chứng: không có brief gốc và điểm duyệt chéo thì gửi sớm cũng không ai có trách nhiệm đối chiếu.'} },
  { type:'mcq', stem:'Bạn là người chủ trì bên hãng, còn hai tuần. Bạn làm gì với video KOL?',
    options:[{k:'a',t:'Giữ nguyên để kịp lịch, coi như hai thông điệp bổ trợ cho nhau'},{k:'b',t:'Cắt kênh KOL khỏi chiến dịch để tránh làm rối thông điệp'},
             {k:'c',t:'Yêu cầu TVC đổi sang nói về giá rẻ cho khớp với video KOL đã quay xong'},{k:'d',t:'Giữ phần quay được, dựng lại lời thoại và đoạn cuối theo ý độ bền'}],
    answer:'d', why:{a:'Hai thông điệp trái nhau không bổ trợ; khách sẽ nhớ mơ hồ.',
      b:'Cắt kênh làm mất vai "làm tin" trong hành trình.',
      c:'Đổi ý tưởng chung để khớp một kênh là đi ngược thứ tự: ý tưởng đi trước.',
      d:'Đúng. Sửa với chi phí thấp nhất mà vẫn đưa KOL về ý chung.'} },
  { type:'mcq', stem:'Trong brief gốc gửi cho mọi agency, phần nào quan trọng nhất để tránh lệch thông điệp?',
    options:[{k:'a',t:'Ý tưởng chung, đối tượng, vai trò từng kênh và chỉ số'},{k:'b',t:'Bảng giá và điều khoản thanh toán cho từng agency'},
             {k:'c',t:'Danh sách người liên hệ của từng agency, kèm số điện thoại và giờ làm việc'},{k:'d',t:'Lịch sử các chiến dịch cũ trong 5 năm qua'}],
    answer:'a', why:{a:'Đúng. Đó là phần mọi bên cần giống nhau.',
      b:'Điều khoản quan trọng về hợp đồng, nhưng không giữ thông điệp.',
      c:'Thông tin liên hệ cần, nhưng không định hướng nội dung.',
      d:'Tham khảo hữu ích, nhưng không thay được ý tưởng hiện tại.'} },
  { type:'calc', stem:'Duyệt chéo gồm 4 buổi, mỗi buổi 5 người họp 2 giờ, giá công trung bình 400.000 đồng một giờ (số minh hoạ). Quay lại vì lệch thông điệp tốn 80 triệu. Chi phí duyệt bằng bao nhiêu phần trăm chi phí quay lại?',
    unit:'%', ans:20, tol:0.5, wrong:[[16,'NHAM_DIEM_PHAN_TRAM'],[500,'SAI_MAU_SO']], errors:['NHAM_DIEM_PHAN_TRAM','SAI_MAU_SO'],
    steps:['Giờ công = 4 buổi × 5 người × 2 giờ = 40 giờ; 40 × 400.000 = 16 triệu.','16 ÷ 80 = <b>20%</b>.','Nếu khả năng lệch thông điệp khi không duyệt cao hơn 20%, duyệt chéo đã có lời về kỳ vọng chi phí.'] },
  { type:'mcq', stem:'Vì sao cần điểm duyệt chéo ở bước kịch bản chứ không đợi bản dựng hoàn chỉnh?',
    options:[{k:'a',t:'Vì agency sáng tạo muốn khoe ý tưởng sớm với các bên khác'},{k:'b',t:'Vì sửa kịch bản rẻ hơn nhiều so với quay lại'},
             {k:'c',t:'Vì bản dựng hoàn chỉnh thường mất bảo mật khi gửi đi nhiều nơi'},{k:'d',t:'Vì duyệt ở bước kịch bản thì không cần duyệt ở các bước sau nữa'}],
    answer:'b', why:{a:'Mục đích là bắt lệch sớm, không phải khoe.',
      b:'Đúng. Phát hiện lệch trên giấy chỉ tốn một buổi họp.',
      c:'Bảo mật là chuyện phụ; lý do chính là chi phí sửa.',
      d:'Vẫn cần duyệt bản dựng thô; kịch bản chỉ là điểm đầu.'} },
  { type:'mcq', stem:'Một startup chỉ có một freelancer thiết kế và tự chạy quảng cáo. Nguyên tắc điều phối nào vẫn cần?',
    options:[{k:'a',t:'Chỉ cần trao đổi miệng hằng tuần, vì hai người hiểu nhau rất nhanh'},{k:'b',t:'Cần một cố vấn độc lập bên ngoài để chốt mỗi khi hai bên bất đồng'},
             {k:'c',t:'Vẫn cần một brief gốc ngắn ghi ý tưởng, đối tượng và vai kênh'},{k:'d',t:'Cần quy trình duyệt ba cấp như doanh nghiệp lớn để tránh sai sót'}],
    answer:'c', why:{a:'Lời nói mỗi người nhớ một cách; hai người vẫn có thể hiểu ý tưởng khác nhau nếu không viết ra.',
      b:'Với hai người, chủ doanh nghiệp tự quyết được; điều thiếu là văn bản gốc để cả hai cùng nhìn.',
      c:'Đúng. Quy mô nhỏ vẫn cần một văn bản gốc; nó chỉ ngắn hơn.',
      d:'Ba cấp duyệt làm chậm hai người mà không thêm thông tin nào về ý tưởng chung.'} },
  { type:'mcq', stem:'Agency media muốn đổi tỉ lệ ngân sách giữa các kênh sau tuần đầu. Ai nên quyết?',
    options:[{k:'a',t:'Người chủ trì bên hãng, vì CPA thấp của kênh chốt có thể nhờ KOL làm nóng trước'},{k:'b',t:'Agency media, vì họ nắm số liệu quảng cáo rõ nhất và chịu trách nhiệm hiệu quả'},
             {k:'c',t:'Agency sáng tạo, vì họ là người nghĩ ra ý tưởng chung của chiến dịch'},{k:'d',t:'Bộ phận kế toán, vì quyết định này liên quan trực tiếp đến phân bổ tiền'}],
    answer:'a', why:{a:'Đúng. CPA thấp ở kênh chốt thường là kết quả của kênh làm nóng; cắt KOL có thể làm CPA tăng sau vài tuần, nên người giữ bức tranh chung phải quyết.',
      b:'Họ có số liệu tốt nhưng chỉ nhìn chỉ số của kênh mình, và thù lao thường gắn với mức chi, nên khó là người cân bằng vai các kênh.',
      c:'Có ý tưởng chung không cho họ quyền hay số liệu để quyết ngân sách media.',
      d:'Kế toán kiểm soát chi theo hợp đồng, không đánh giá vai từng kênh trong chiến lược.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kn10-08', skill:'measure', read:'7 phút', t:'Đo từng kênh hay đo cả chiến dịch?',
  situation:'Sau chiến dịch 2 tỷ của một hãng dầu gội, mỗi kênh gửi báo cáo riêng: TikTok 40 triệu lượt xem, KOL 2.000 đơn qua mã giảm giá, Shopee 6.000 đơn, Google 1.500 đơn. Cộng lại 9.500 đơn. Nhưng kho chỉ xuất 7.000 đơn mới trong kỳ. Sếp hỏi: rốt cuộc chiến dịch hiệu quả đến đâu?',
  concept:{ name:'Chỉ số từng kênh và chỉ số chung',
    body:'Mỗi kênh có <b>chỉ số theo vai</b>: độ phủ cho kênh làm biết, xem hết hoặc tìm kiếm tăng cho kênh làm tin, đơn và ROAS cho kênh chốt, mua lại cho kênh giữ khách. Nhưng mỗi nền tảng tự nhận công cho cùng một đơn, nên cộng các báo cáo kênh thường lớn hơn thực tế. Vì vậy cần thêm <b>một chỉ số chung</b> ở cấp doanh nghiệp: đơn thật, doanh thu thật, mức nhớ thương hiệu. Ngay đơn thật cũng chưa phải đơn do chiến dịch tạo ra, vì một phần là <b>đơn nền</b> vốn có dù không chạy. Phần đáng tính công là <b>đơn tăng thêm</b> = đơn kỳ chạy − đơn nền, cùng mùa vụ, cùng cách trừ hoàn. Chỉ số kênh để chỉnh kênh; chỉ số chung để trả lời có đáng tiền không, bằng cách đặt đơn tăng thêm cạnh lãi gộp.' },
  example:'Hãng dầu gội lấy chỉ số chung là đơn thật từ kho. Kho xuất 7.000 đơn, nhưng kỳ liền trước không chạy quảng cáo mà vẫn xuất khoảng 5.000 đơn nền (số minh hoạ). Đơn tăng thêm chỉ khoảng 2.000, nên 2 tỷ ÷ 2.000 = 1 triệu đồng mỗi đơn tăng thêm, không phải 286.000. Mỗi đơn trung bình 300.000đ, biên gộp 40%, tức lãi gộp 120.000đ: trong kỳ chưa hoàn vốn, và chiến dịch chỉ biện hộ được nếu khách mua lại. Chỉ số kênh giữ để chỉnh từng kênh; phần chênh 2.500 đơn giữa báo cáo kênh và kho phần lớn là đơn bị nhiều kênh cùng nhận công.',
  takeaway:'Chỉ số kênh để chỉnh kênh; chỉ số chung, tính trên đơn tăng thêm so với đơn nền, mới trả lời chiến dịch có đáng tiền không.',
  apply:'Lấy một chiến dịch có nhiều kênh. Nói trong 60 giây: chỉ số chung là gì, đơn nền lấy ở kỳ nào, và đơn tăng thêm là bao nhiêu.',
  mistakes:['Cộng số đơn từ báo cáo của mỗi nền tảng làm tổng kết quả.','Đo kênh làm biết bằng số đơn như kênh chốt.','Coi toàn bộ đơn của kho trong kỳ chạy là đơn do chiến dịch tạo ra, không trừ đơn nền.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao cộng báo cáo các kênh được 9.500 đơn mà kho chỉ xuất 7.000?',
    options:[{k:'a',t:'Kho ghi thiếu số đơn vì hệ thống quản lý bị lỗi'},{k:'b',t:'Nhiều đơn bị hoàn nên số xuất kho giảm so với số đặt ban đầu'},
             {k:'c',t:'Có kênh báo cáo gian lận số đơn để được gia hạn hợp đồng'},{k:'d',t:'Cùng một đơn được nhiều kênh cùng nhận công vì khách đã chạm nhiều kênh'}],
    answer:'d', why:{a:'Có thể, nhưng số kho thường là nguồn tin cậy nhất; không có lý do nghi nó trước.',
      b:'Hoàn đơn có thể góp một phần; muốn biết phần nào thì đối soát theo mã đơn. Nhận công trùng vẫn là nguyên nhân khả dĩ nhất của chênh 2.500 đơn.',
      c:'Không cần giả định gian lận; mỗi nền tảng đều tự nhận công theo cách của nó.',
      d:'Đúng. Khách xem TikTok, tìm Google rồi mua Shopee — ba nền tảng cùng ghi một đơn.'} },
  { type:'mcq', stem:'Sếp hỏi chiến dịch 2 tỷ có đáng tiền không. Kho xuất 7.000 đơn, kỳ nền 5.000 đơn, mỗi đơn lãi gộp 120.000đ. Bạn chọn báo cáo con số nào?',
    options:[{k:'a',t:'Chi phí 286.000đ mỗi đơn, thấp hơn giá đơn 300.000đ nên chiến dịch chắc chắn đáng tiền'},{k:'b',t:'Tổng 9.500 đơn từ báo cáo nền tảng, vì đó là số các kênh đã ghi nhận chính thức'},
             {k:'c',t:'Khoảng 1 triệu đồng mỗi đơn tăng thêm, so với lãi gộp 120.000đ mỗi đơn: chưa hoàn vốn trong kỳ'},{k:'d',t:'Mức nhớ thương hiệu tăng 9 điểm, vì chỉ số nhớ mới phản ánh chiến dịch có đáng tiền không'}],
    answer:'c', why:{a:'Sai hai lần: chia cho cả đơn nền, và so chi phí với doanh thu thay vì lãi gộp.',
      b:'Tổng báo cáo nền tảng bị đếm trùng và gồm cả đơn nền; báo lên sẽ phóng đại hiệu quả.',
      c:'Đúng. 2 tỷ ÷ 2.000 đơn tăng thêm = 1 triệu, lớn hơn nhiều so với lãi gộp 120.000đ; phần còn lại phải biện hộ bằng mua lại.',
      d:'Mức nhớ là một giá trị thật nhưng không phải bằng chứng hoàn vốn; nó cần đặt cạnh số đơn tăng thêm và lãi gộp.'} },
  { type:'calc', stem:'Kho xuất 7.000 đơn trong kỳ chiến dịch; kỳ nền cùng mùa vụ xuất 5.000 đơn. Chi 2 tỷ. Chi phí mỗi đơn tăng thêm là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:1000, tol:1, wrong:[[286,'SAI_MAU_SO'],[400,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Đơn tăng thêm = 7.000 − 5.000 = 2.000 đơn.','2 tỷ = 2.000.000 nghìn đồng; 2.000.000 ÷ 2.000 = <b>1.000 nghìn đồng</b> (1 triệu) mỗi đơn tăng thêm. Chia cho 7.000 ra 286 là tính cả đơn nền; chia cho 5.000 ra 400 là lấy nhầm đơn nền.'] },
  { type:'mcq', stem:'Kho ghi 7.000 đơn xuất trong kỳ chạy, sau đó 700 đơn bị hoàn. Kỳ nền 5.000 đơn. Cách tính đơn tăng thêm nào đúng?',
    options:[{k:'a',t:'Trừ 700 đơn hoàn, và trừ hoàn theo cùng cách ở kỳ nền, rồi mới lấy chênh lệch'},{k:'b',t:'Giữ 7.000 vì kho đã ghi đủ, hoàn đơn là việc của bộ phận chăm sóc khách'},
             {k:'c',t:'Chỉ trừ 700 đơn hoàn ở kỳ chạy, kỳ nền giữ nguyên để so với số xuất kho'},{k:'d',t:'Cộng thêm 700 vào đơn tăng thêm vì khách hoàn đơn vẫn đã bị chiến dịch tác động'}],
    answer:'a', why:{a:'Đúng. Hai kỳ phải cùng định nghĩa (cùng trừ hoàn), nếu không chênh lệch phản ánh cách đếm chứ không phải chiến dịch.',
      b:'Đơn hoàn không mang doanh thu về; giữ nguyên làm chi phí mỗi đơn đẹp giả tạo.',
      c:'Chỉ trừ một bên làm kỳ chạy bị thiệt so với kỳ nền, hai con số không cùng loại.',
      d:'Đơn hoàn không phải đơn tăng thêm; cộng vào là tính một thứ không có doanh thu.'} },
  { type:'mcq', stem:'Một chuỗi nhà thuốc chạy chiến dịch trên Facebook, Zalo và tờ rơi. Chỉ số chung hợp lý nhất là gì?',
    options:[{k:'a',t:'Tổng lượt thích trên cả ba kênh cộng lại'},{k:'b',t:'Số khách mới và doanh thu tại quầy so với cùng kỳ'},
             {k:'c',t:'Số tờ rơi đã phát ra trong tháng'},{k:'d',t:'Số tin nhắn Zalo được gửi đi thành công, vì đó là kênh chạm trực tiếp tới khách'}],
    answer:'b', why:{a:'Lượt thích không đo được việc khách có đến mua.',
      b:'Đúng. Đo ở cấp cửa hàng, không phụ thuộc kênh nào tự nhận công.',
      c:'Đó là chỉ số đầu vào của một kênh, không phải kết quả.',
      d:'Gửi thành công là đầu vào; chưa nói gì về người đến mua.'} },
  { type:'mcq', stem:'Chỉ số kênh vẫn cần dù đã có chỉ số chung. Vì sao?',
    options:[{k:'a',t:'Để chia thưởng cho từng agency theo phần đóng góp chính xác'},{k:'b',t:'Để thay thế chỉ số chung khi số kho chưa có hoặc bị chậm vài tuần'},
             {k:'c',t:'Vì nền tảng yêu cầu phải báo cáo chỉ số riêng'},{k:'d',t:'Để biết kênh nào đang làm tốt vai của nó và chỉnh ngay trong lúc chạy'}],
    answer:'d', why:{a:'Chỉ số kênh bị nhận công trùng nên không chia thưởng chính xác được.',
      b:'Dùng tạm thì được, nhưng không thay thế được; đó chính là lỗi cộng trùng.',
      c:'Nền tảng không bắt buộc điều đó.',
      d:'Đúng. Chỉ số kênh là công cụ lái trong lúc chạy.'} },
  { type:'mcq', stem:'Mức nhớ thương hiệu đo trước chiến dịch là 18%, sau chiến dịch là 27%. Cách nói nào đúng?',
    options:[{k:'a',t:'Mức nhớ tăng 9%, tức là gần gấp đôi so với trước'},{k:'b',t:'Mức nhớ tăng 9 điểm phần trăm, tức tăng 50% so với mức trước đó'},
             {k:'c',t:'Mức nhớ tăng 27%, vì đó là con số đo được sau chiến dịch'},{k:'d',t:'Mức nhớ tăng 150% vì 27 chia cho 18 bằng 1,5'}],
    answer:'b', why:{a:'9 là điểm phần trăm, không phải 9%; và 27/18 là 1,5 lần chứ không gần gấp đôi.',
      b:'Đúng. 27 − 18 = 9 điểm; 9 ÷ 18 = 50% so với mức cũ.',
      c:'27% là mức sau, không phải mức tăng.',
      d:'1,5 lần nghĩa là tăng 50%, không phải 150%.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:kn10-09', skill:'channel', read:'6 phút', t:'Rà soát gì trước khi bấm chạy?',
  situation:'Tối trước ngày chạy chiến dịch 11.11, một hãng giày phát hiện: link trong bio TikTok dẫn tới trang 404, mã giảm giá của KOL chưa được tạo trên Shopee, banner sàn ghi giảm 30% còn email ghi giảm 25%. Còn 8 tiếng. Không ai trong nhóm có danh sách kiểm tra chung.',
  concept:{ name:'Danh sách rà soát trước khi chạy',
    body:'Một kế hoạch tích hợp có nhiều mắt xích; hỏng một chỗ là đứt cả chuỗi. Rà soát đi theo <b>hành trình của khách</b>, không theo từng kênh: bấm thử từ quảng cáo tới thanh toán trên điện thoại, đặt một đơn thử, nhập thử từng mã, so mọi con số (giá, % giảm, ngày) giữa các ấn phẩm và thử tải cho giờ cao điểm. Xếp lỗi theo <b>ba mức</b>: chặn mua (khách không trả tiền được), sai niềm tin (con số lệch, hứa một đằng làm một nẻo), mất đo lường (pixel, UTM hỏng nên chạy xong không biết kết quả). Sửa theo thứ tự số khách bị chặn nhân mức nặng, không theo thứ tự tìm thấy. Danh sách viết từ trước, mỗi dòng có người chịu trách nhiệm, rà xong 48 giờ trước giờ G.' },
  example:'Hãng giày viết danh sách 20 dòng chia năm nhóm: đường đi, con số, mã và kho, đo lường, người trực. Rà soát 48 giờ trước giờ chạy xếp ba lỗi cũ theo ba mức: link 404 và mã KOL chưa tạo là chặn mua, lệch 30% với 25% là sai niềm tin. Một đơn thử trên điện thoại còn bắt thêm lỗi: mã chỉ áp cho đơn từ 299.000đ trong khi KOL hứa mọi đơn. Bốn lỗi sửa trong 6 giờ (số minh hoạ), còn dư thời gian thử tải. Chờ đến tối trước ngày chạy thì bốn lỗi chiếm hết 8 tiếng và vẫn lọt một lỗi.',
  takeaway:'Rà soát theo đường đi của khách, bằng điện thoại, 48 giờ trước giờ chạy.',
  apply:'Nghĩ về một chiến dịch sắp chạy. Nói trong 60 giây năm thứ bạn sẽ bấm thử trước.',
  mistakes:['Mỗi kênh tự kiểm tra phần mình mà không ai đi hết đường của khách.','Rà soát trên máy tính trong khi phần lớn khách dùng điện thoại.'],
  q:[
  { type:'mcq', stem:'Đoán trước, theo số minh hoạ: link bio có 8.000 lượt vào, 4% ra đơn, 70% người gặp lỗi không tìm lại được hãng; mã KOL có 1.500 khách sẵn sàng nhập mã, 30% ra đơn; lệch % giảm làm 2.000 khách phân vân, 5% bỏ mua. Lỗi nào làm mất nhiều đơn nhất nếu lọt?',
    options:[{k:'a',t:'Banner và email ghi hai mức giảm khác nhau'},{k:'b',t:'Mã giảm giá KOL chưa tạo trên Shopee'},
             {k:'c',t:'Link bio TikTok dẫn tới trang 404'},{k:'d',t:'Chưa đủ dữ liệu để xếp; phải chạy rồi mới biết lỗi nào nặng nhất'}],
    answer:'b', why:{a:'2.000 × 5% = 100 đơn; lệch con số làm mất lòng tin nhưng khách vẫn mua được.',
      b:'Đúng. 1.500 × 30% = 450 đơn, và đó là khách đã đi hết chuỗi, thất bại ở bước trả tiền.',
      c:'8.000 × 4% × 70% = 224 đơn; ngay cả khi 100% người gặp lỗi bỏ đi cũng chỉ 320, vẫn thấp hơn 450.',
      d:'Ước lượng thô trước khi chạy vẫn xếp được thứ tự; sai số nhỏ không đảo được chênh 450 và 224.'} },
  { type:'mcq', stem:'Còn 8 tiếng, mỗi lỗi sửa mất khoảng 3 tiếng nên bạn chỉ kịp hai lỗi. Theo số ở câu trước, bạn chọn sửa hai lỗi nào?',
    options:[{k:'a',t:'Link bio và lệch % giảm, vì hai lỗi này khách thấy ngay từ đầu chuỗi'},{k:'b',t:'Lệch % giảm và email, vì chỉ cần sửa chữ nên nhanh và không cần bên khác'},
             {k:'c',t:'Mã KOL và link bio; lệch % giảm thêm dòng đính chính, sửa ngay sau khi chạy'},{k:'d',t:'Mã KOL và lệch % giảm, vì cả hai nằm ở bước khách đã quyết định mua'}],
    answer:'c', why:{a:'Link bio mất 224 đơn nhưng bỏ mã KOL là bỏ 450 đơn, lớn hơn lỗi lệch % giảm gấp bốn lần.',
      b:'Dễ sửa không phải tiêu chí; đây là hai lỗi nhỏ nhất, còn hai lỗi chặn mua vẫn lọt.',
      c:'Đúng. 450 + 224 đơn là phần chặn mua lớn nhất; lệch % giảm (100 đơn) có cách giảm nhẹ rẻ bằng đính chính.',
      d:'Chọn đúng lỗi lớn nhất nhưng bỏ link bio, nên khách đến từ TikTok vẫn gặp trang 404.'} },
  { type:'mcq', stem:'Vì sao nên rà soát theo hành trình khách thay vì theo từng kênh?',
    options:[{k:'a',t:'Vì lỗi hay nằm ở chỗ nối giữa hai kênh mà không kênh nào tự thấy'},{k:'b',t:'Vì agency không chịu kiểm tra phần của mình'},
             {k:'c',t:'Vì kiểm tra theo kênh tốn nhiều người hơn'},{k:'d',t:'Vì hành trình khách ngắn hơn danh sách kênh nên kiểm tra nhanh hơn và ít sót hơn'}],
    answer:'a', why:{a:'Đúng. Link từ TikTok sang Shopee, mã từ KOL sang sàn — chỗ nối là nơi rơi.',
      b:'Agency vẫn kiểm tra phần mình; vấn đề là không ai kiểm tra chỗ nối.',
      c:'Số người không phải lý do chính.',
      d:'Hành trình thường dài hơn và phức tạp hơn; lợi ích là bắt lỗi chỗ nối.'} },
  { type:'calc', stem:'Giờ cao điểm 11.11 dự kiến 9.000 lượt vào trang mỗi giờ. Thử tải cho thấy trang thanh toán chịu được 100 lượt mỗi phút. Lượng khách dự kiến vượt công suất bao nhiêu phần trăm?',
    unit:'%', ans:50, tol:0.5, wrong:[[33.3,'SAI_MAU_SO'],[150,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Đổi giờ ra phút: 9.000 ÷ 60 = 150 lượt mỗi phút.','Vượt = (150 − 100) ÷ 100 = <b>50%</b> so với công suất. Chia cho 150 thì ra 33,3% — sai mẫu số vì so với tải thay vì công suất.'] },
  { type:'mcq', stem:'Quán trà sữa vừa cài khuyến mãi mua 1 tặng 1 trên Grab và đăng fanpage; mọi thứ trông đã xong. Việc nào cho bằng chứng khuyến mãi chạy đúng?',
    options:[{k:'a',t:'Đặt thử một đơn trên Grab bằng điện thoại khác và xem tổng tiền cuối cùng'},{k:'b',t:'Nhờ nhân viên xác nhận bảng khuyến mãi đã được gửi lên đúng mẫu'},
             {k:'c',t:'Xem lại ảnh banner fanpage và xác nhận khớp với bản thảo đã duyệt'},{k:'d',t:'Mở trang quản lý Grab và xác nhận các ô khuyến mãi đều đã điền'}],
    answer:'a', why:{a:'Đúng. Chỉ đơn thử đi hết đường mua mới cho thấy khách thực sự trả bao nhiêu và có nhận quà không.',
      b:'Gửi đúng mẫu chưa cho biết hệ thống áp ra sao; đó là lời tường thuật, không phải bằng chứng.',
      c:'Banner khớp bản thảo chỉ kiểm lời hứa, không kiểm việc ứng dụng thực hiện lời hứa đó.',
      d:'Cấu hình điền đủ vẫn có thể áp sai điều kiện; cấu hình khác với hành vi thật khi khách bấm.'} },
  { type:'mcq', stem:'Vì sao nên rà soát xong khoảng 48 giờ trước giờ chạy?',
    options:[{k:'a',t:'Vì nền tảng quảng cáo cần 48 giờ để duyệt các thay đổi'},{k:'b',t:'Vì đó là thời gian khách bắt đầu tìm kiếm sản phẩm trên sàn'},
             {k:'c',t:'Vì đủ thời gian sửa lỗi cần bên khác làm, như tạo mã hay sửa trang'},{k:'d',t:'Vì rà soát sớm hơn thì các bên sẽ quên và làm sai lại'}],
    answer:'c', why:{a:'Thời gian duyệt khác nhau; 48 giờ là khoảng đệm để sửa, không phải quy định.',
      b:'Không liên quan đến hành vi tìm kiếm.',
      c:'Đúng. Nhiều lỗi cần người khác sửa; cần thời gian đệm.',
      d:'Sớm không làm người ta quên; muộn mới làm không kịp sửa.'} },
  { type:'mcq', stem:'Dòng nào NÊN có trong danh sách rà soát nhưng hay bị quên, vì không ai nhận phần của mình?',
    options:[{k:'a',t:'Tên và ảnh đại diện của KOL trên các bài khớp bản đã duyệt'},{k:'b',t:'Số bài đăng đã chuẩn bị đủ cho cả tuần đầu của chiến dịch'},
             {k:'c',t:'Ảnh và số liệu trên banner khớp với bản thiết kế cuối cùng'},{k:'d',t:'Pixel, UTM bắn đúng và có người trực sửa lỗi trong đêm 11.11'}],
    answer:'d', why:{a:'Mỗi KOL và agency thường tự kiểm phần này; ít khi là chỗ bị quên.',
      b:'Lịch bài là việc hằng ngày của nhóm nội dung, luôn có người theo dõi.',
      c:'Đối chiếu thiết kế là việc của designer trước khi bàn giao nên hiếm khi bị bỏ sót.',
      d:'Đúng. Đo lường và người trực nằm giữa các nhóm: không ai sở hữu, lỗi mới lộ khi đã mất đơn.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:kn10-10', skill:'channel', read:'7 phút', t:'Một kênh hỏng giữa chừng thì làm gì?',
  situation:'Tuần thứ hai của chiến dịch ra mắt nồi chiên không dầu, tài khoản quảng cáo Facebook của hãng bị tạm khoá để xem xét. Kênh này chiếm 40% ngân sách 1 tỷ và đang mang về phần lớn lượt vào trang. Nhóm hoảng loạn: có người đòi dừng cả chiến dịch, có người đòi dồn hết tiền sang TikTok ngay trong đêm.',
  concept:{ name:'Kế hoạch dự phòng (plan B)',
    body:'Kế hoạch tích hợp tốt viết sẵn <b>phương án dự phòng</b> cho những kênh rủi ro cao: tài khoản bị khoá, KOL gặp sự cố, sàn đổi chính sách, hết hàng. Mỗi phương án ghi: dấu hiệu kích hoạt, kênh thay thế, phần tiền chuyển sang, người quyết. Kênh thay thế nên đã được <b>chạy thử nhỏ từ trước</b> để có sẵn tài khoản, nội dung và số liệu. Không dồn hết tiền sang một kênh chưa thử: nó cần thời gian học, và tăng ngân sách thì nên theo từng bước. Phòng ngừa từ đầu: nhiều quản trị viên, một tài khoản dự phòng đã xác minh, và danh sách khách xuất ra lưu riêng, vì mất tài khoản là mất luôn tệp nhắm lại và dữ liệu đo.' },
  example:'Kế hoạch dự phòng ghi: nếu Facebook dừng quá 24 giờ, người quyết là trưởng nhóm, phần tiền Facebook còn lại 400 triệu (dùng trong 14 ngày) chuyển sang TikTok và quảng cáo tìm kiếm. TikTok đã chạy thử 4 triệu/ngày suốt 3 tuần, có sẵn nội dung và tệp. Quy tắc tăng: không quá 30% mỗi 3 ngày (ngưỡng minh hoạ, mỗi nền tảng một khác). Đi bước như vậy, 14 ngày TikTok mới nhận khoảng 126 triệu. Phần còn lại chia cho tìm kiếm thương hiệu, Zalo OA và giữ lại chờ Facebook mở. Ý tưởng và thông điệp giữ nguyên, chỉ đổi đường đi.',
  takeaway:'Viết sẵn dấu hiệu, kênh thay thế và người quyết — trước khi cần đến.',
  apply:'Chọn kênh bạn phụ thuộc nhiều nhất. Nói trong 60 giây: nếu nó dừng ngày mai, tiền chuyển đi đâu.',
  mistakes:['Dồn hết tiền sang một kênh chưa từng chạy thử trong một đêm.','Dừng cả chiến dịch vì một kênh gặp sự cố.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì dễ xảy ra nếu dồn 400 triệu sang TikTok ngay trong đêm khi chưa từng chạy thử?',
    options:[{k:'a',t:'Chi phí tăng vọt vì hệ thống chưa kịp học và tệp phù hợp cạn nhanh'},{k:'b',t:'Kết quả tốt hơn Facebook vì TikTok đang là kênh được ưa chuộng'},
             {k:'c',t:'TikTok từ chối nhận tiền vì tài khoản quá mới'},{k:'d',t:'Không khác gì, vì cùng số tiền thì tiếp cận cùng số người mỗi kênh'}],
    answer:'a', why:{a:'Đúng. Kênh mới cần thời gian học; bơm đột ngột thường làm chi phí tăng.',
      b:'Kênh phổ biến không đảm bảo hiệu quả khi chưa có nội dung và dữ liệu.',
      c:'Nền tảng thường vẫn nhận tiền; vấn đề là hiệu quả.',
      d:'Giá mỗi lượt tiếp cận khác nhau giữa các kênh và thay đổi khi bơm đột ngột.'} },
  { type:'mcq', stem:'Bạn là trưởng nhóm, tài khoản Facebook vừa bị khoá. Bạn làm gì trong 24 giờ đầu?',
    options:[{k:'a',t:'Dừng cả chiến dịch cho đến khi Facebook mở lại tài khoản'},{k:'b',t:'Chuyển cả 400 triệu sang TikTok ngay trong đêm'},
             {k:'c',t:'Gửi kháng nghị, tăng Zalo OA, và kích hoạt dự phòng nếu quá 24 giờ'},{k:'d',t:'Mở ngay một tài khoản quảng cáo mới trên cùng trang để chạy tiếp'}],
    answer:'c', why:{a:'Các kênh khác vẫn chạy được; dừng tất cả là mất phần còn lại.',
      b:'Dồn hết một lần làm chi phí tăng và bỏ qua phần chuyển sang tìm kiếm.',
      c:'Đúng. Làm việc có thể làm ngay, và theo đúng dấu hiệu kích hoạt đã viết sẵn.',
      d:'Tài khoản mới dùng lại trang, thẻ và thiết bị cũ dễ bị coi là lách chính sách và kéo thêm tài khoản liên quan bị khoá.'} },
  { type:'calc', stem:'TikTok đang chạy 4 triệu/ngày. Quy tắc dự phòng: mỗi 3 ngày tăng tối đa 30% so với mức hiện tại. Sau hai lần tăng, ngân sách một ngày là bao nhiêu?',
    unit:'triệu/ngày', ans:6.76, tol:0.05, wrong:[[6.4,'SAI_TINH_TOAN'],[5.2,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Lần 1: 4 × 1,3 = 5,2 triệu/ngày.','Lần 2: 5,2 × 1,3 = <b>6,76 triệu/ngày</b>.','Cộng thẳng 30% + 30% lên mức gốc sẽ ra 6,4, thấp hơn; mức tăng chồng lên mức đã tăng. Tốc độ này nghĩa là TikTok không thể nuốt 400 triệu trong vài ngày.'] },
  { type:'mcq', stem:'Trong phương án dự phòng, thành phần nào giúp tránh tranh cãi lúc khủng hoảng?',
    options:[{k:'a',t:'Danh sách các kênh có thể dùng được trên thị trường hiện nay'},{k:'b',t:'Dấu hiệu kích hoạt rõ ràng và tên người được quyền quyết'},
             {k:'c',t:'Bảng so sánh chi phí trung bình của các kênh trong ngành'},{k:'d',t:'Lịch sử các lần tài khoản bị khoá của những hãng khác trong ngành'}],
    answer:'b', why:{a:'Danh sách dài không giúp quyết nhanh.',
      b:'Đúng. Khi đã ghi sẵn điều kiện và người quyết, không ai phải tranh luận lúc gấp.',
      c:'Chi phí tham khảo có ích, nhưng không trả lời "khi nào" và "ai".',
      d:'Thông tin đó ít giúp gì cho quyết định lúc sự cố.'} },
  { type:'mcq', stem:'Vì sao kênh dự phòng nên được chạy thử nhỏ từ trước chiến dịch?',
    options:[{k:'a',t:'Để nền tảng giảm giá quảng cáo cho tài khoản đã chi tiêu từ trước'},{k:'b',t:'Để thay thế hẳn kênh chính nếu kết quả thử tốt hơn'},
             {k:'c',t:'Để có thêm số liệu đẹp gửi sếp trong báo cáo tuần của nhóm'},{k:'d',t:'Để có sẵn tài khoản, nội dung và số liệu khi cần tăng tiền gấp'}],
    answer:'d', why:{a:'Nền tảng không giảm giá theo mức chi tiêu trước đó; giá do đấu giá và độ cạnh tranh.',
      b:'Có thể điều chỉnh sau, nhưng mục đích chính là sẵn sàng khi cần.',
      c:'Báo cáo đẹp không phải mục đích của dự phòng.',
      d:'Đúng. Kênh đã có nền thì tăng tiền nhanh và ít rủi ro hơn.'} },
  { type:'mcq', stem:'Một KOL chính của chiến dịch vướng tranh cãi cá nhân trước ngày đăng. Phương án dự phòng hợp lý là gì?',
    options:[{k:'a',t:'Vẫn đăng như kế hoạch vì hợp đồng đã ký và video đã quay xong'},{k:'b',t:'Hoãn bài KOL, dùng KOL dự bị đã duyệt và giữ nguyên ý tưởng chiến dịch'},
             {k:'c',t:'Đổi ý tưởng chiến dịch để tránh bị liên hệ với KOL đó'},{k:'d',t:'Đăng lời xin lỗi thay mặt KOL trên fanpage của hãng để chủ động xử lý khủng hoảng'}],
    answer:'b', why:{a:'Đăng khi đang tranh cãi dễ kéo thương hiệu vào chuyện không liên quan.',
      b:'Đúng. Đổi người, giữ ý tưởng — đúng tinh thần dự phòng.',
      c:'Ý tưởng không có lỗi; đổi ý tưởng là phản ứng quá tay.',
      d:'Hãng không nên phát ngôn thay cho chuyện cá nhân của KOL.'} },
  { type:'mcq', stem:'Khi chuyển tiền sang kênh dự phòng, điều gì KHÔNG nên đổi?',
    options:[{k:'a',t:'Tỉ lệ ngân sách giữa các kênh đang chạy'},{k:'b',t:'Định dạng nội dung cho kênh mới'},
             {k:'c',t:'Chỉ số theo dõi hằng ngày của từng kênh trong lúc chuyển đổi'},{k:'d',t:'Ý tưởng chung và thông điệp của chiến dịch'}],
    answer:'d', why:{a:'Tỉ lệ ngân sách chính là thứ phải đổi khi kích hoạt dự phòng.',
      b:'Kênh mới cần định dạng riêng.',
      c:'Theo dõi sát hơn là cần; chỉ số của kênh mới cũng khác.',
      d:'Đúng. Đổi đường đi, không đổi câu chuyện.'} }
  ] }

] });
